import java.util.Scanner;

public class Main {

    static final int MAXN = 266666;
    static long[] fact = new long[MAXN + 1];
    static long[] inv_fact = new long[MAXN + 1];
    static long[][] dp_state = new long[30][22];
    static long[][] a_data = new long[18][1 << 17]; // size 131072 for bitmask of 17 bits
    static long[] b_res = new long[1 << 17];
    static int M;

    static long bin_pow(long base, long exp) {
        long res = 1;
        long cur = base;
        while (exp > 0) {
            if ((exp & 1) != 0) res = (res * cur) % M;
            cur = (cur * cur) % M;
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        M = sc.nextInt();

        if (n % 2 != 0) {
            System.out.println(bin_pow(k, n));
            return;
        }

        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (fact[i - 1] * i) % M;
        }

        inv_fact[n] = bin_pow(fact[n], M - 2);
        for (int i = n - 1; i >= 0; i--) {
            inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % M;
        }

        int half_n = n >> 1;
        for (int i = 0; i <= half_n; i++) {
            int popcnt = Integer.bitCount(i);
            a_data[popcnt][i] = inv_fact[i * 2];
        }

        for (int i = 0; i < 17; i++) {
            for (int j = 0; j < 17; j++) {
                for (int u = 0; u < (1 << 17); u++) {
                    if (((u >> j) & 1) != 0) {
                        a_data[i][u] += a_data[i][u ^ (1 << j)];
                    }
                }
            }
        }

        for (int i = 0; i < 17; i++) {
            for (int u = 0; u < (1 << 17); u++) {
                a_data[i][u] %= M;
            }
        }

        int popcnt_half = Integer.bitCount(half_n);
        for (int i = 0; i < (1 << 17); i++) {
            for (int j = 0; j < 22; j++) {
                for (int u = 0; u < 30; u++) {
                    for (int v = 0; v <= 17; v++) {
                        dp_state[j][v] = 0;
                    }
                }
            }

            for (int j = 0; j < 30; j++) {
                for (int v = 0; v < 22; v++) {
                    dp_state[j][v] = 0;
                }
            }
            dp_state[0][0] = 1;

            for (int j = 1; j <= k; j++) {
                for (int u = 0; u <= 17; u++) {
                    for (int v = 0; v + u <= 17; v++) {
                        long val = (a_data[u][i] * dp_state[j - 1][v]) % M;
                        dp_state[j][u + v] += val;
                    }
                    if ((u & 7) == 0) {
                        for (int v = 0; v <= 17; v++) {
                            dp_state[j][v] %= M;
                        }
                    }
                }
            }

            long total = 0;
            for (int v = 0; v <= 17; v++) {
                total += dp_state[k][v];
            }
            total %= M;
            b_res[i] = total;
        }

        for (int i = 0; i < 17; i++) {
            for (int j = 0; j < (1 << 17); j++) {
                if (((j >> i) & 1) != 0) {
                    b_res[j] -= b_res[j ^ (1 << i)];
                }
            }
        }

        long final_ans = ((bin_pow(k, n * 2) - b_res[n] * fact[n * 2]) % M + M) % M;
        System.out.println(final_ans);
        sc.close();
    }
